@Test
public void testGetCanceledBadQueriesStatus() {
    ConcurrentMap<String, SlowQueryDetector.CanceledSlowQueryStatus> canceledBadQueriesStatus = Maps.newConcurrentMap();
    String needReportQueryId = "need-report-query-id";
    //query.cancelTimes > 1 will be reported
    int needReportCanceledTimes = 2;
    String notNeedReportQueryId = "not-need-report-query-id";
    //query.cancelTimes <= 1 will not be reported
    int notNeedReportCanceledTimes = 1;
    long lastCancelTime = System.currentTimeMillis();
    float durationTime = 20.55F;
    canceledBadQueriesStatus.put(needReportQueryId, new SlowQueryDetector.CanceledSlowQueryStatus(needReportQueryId, needReportCanceledTimes, lastCancelTime, durationTime));
    canceledBadQueriesStatus.put(notNeedReportQueryId, new SlowQueryDetector.CanceledSlowQueryStatus(notNeedReportQueryId, notNeedReportCanceledTimes, lastCancelTime, durationTime));
    SlowQueryDetector.addCanceledSlowQueriesStatus(canceledBadQueriesStatus);
    List<HealthResponse.CanceledSlowQueryStatusResponse> slowQueriesStatus = healthService.getCanceledSlowQueriesStatus();
    Assert.assertEquals(1, slowQueriesStatus.size());
    Assert.assertEquals(needReportQueryId, slowQueriesStatus.get(0).getQueryId());
    Assert.assertEquals(needReportCanceledTimes, slowQueriesStatus.get(0).getCanceledTimes());
    Assert.assertEquals(lastCancelTime, slowQueriesStatus.get(0).getLastCanceledTime());
    Assert.assertTrue((durationTime - slowQueriesStatus.get(0).getQueryDurationTime()) * (durationTime - slowQueriesStatus.get(0).getQueryDurationTime()) < 0.00001);
}

