@Test
@OverwriteProp(key = "kylin.metadata.audit-log.max-size", value = "20")
void testAuditLogRotateWhenBackup(JdbcInfo info) throws Exception {
    val tempDir = Files.createTempDir();
    val kylinConfig = getTestConfig();
    kylinConfig.setProperty("kylin.env.hdfs-working-dir", tempDir.getAbsolutePath());
    val resourceStore = ResourceStore.getKylinMetaStore(kylinConfig);
    resourceStore.checkAndPutResource("/UUID", new StringEntity(RandomUtil.randomUUIDStr()), StringEntity.serializer);
    Assert.assertEquals(1, resourceStore.listResourcesRecursively("/").size());
    val url = getTestConfig().getMetadataUrl();
    val jdbcTemplate = info.getJdbcTemplate();
    val table = url.getIdentifier() + "_audit_log";
    JdbcAuditLogStoreTool.prepareJdbcAuditLogStore(table, jdbcTemplate);
    long count = jdbcTemplate.queryForObject("select count(1) from " + table, Long.class);
    val rootPath = new Path(kylinConfig.getHdfsWorkingDirectory()).getParent();
    val rootFS = HadoopUtil.getWorkingFileSystem();
    Assertions.assertThat(rootFS.listStatus(rootPath)).isEmpty();
    metadataBackupService.backupAll();
    // make sure backup is successful
    val rootMetadataPath = new Path(kylinConfig.getHdfsWorkingDirectory() + "/_backup");
    val rootMetadataFS = HadoopUtil.getWorkingFileSystem();
    Assert.assertEquals(1, rootMetadataFS.listStatus(rootMetadataPath).length);
    val path = rootMetadataFS.listStatus(rootMetadataPath)[0].getPath();
    Assert.assertEquals(1, rootMetadataFS.listStatus(path).length);
    val coreMetadataPath = rootMetadataFS.listStatus(path)[0].getPath();
    Assert.assertEquals(2, rootMetadataFS.listStatus(coreMetadataPath).length);
    FSDataInputStream fis = rootMetadataFS.open(new Path(coreMetadataPath.toString() + File.separator + "_image"));
    BufferedReader reader = new BufferedReader(new InputStreamReader(fis, StandardCharsets.UTF_8));
    String image = reader.readLine();
    ImageDesc imageDesc = JsonUtil.readValue(image, ImageDesc.class);
    Assertions.assertThat(imageDesc.getOffset()).isEqualTo(count);
    // assert delete audit_log
    await().atMost(10, TimeUnit.SECONDS).until(() -> {
        long newCount = jdbcTemplate.queryForObject("select count(1) from " + table, Long.class);
        return newCount == 20;
    });
    jdbcTemplate.batchUpdate("DROP ALL OBJECTS");
}

@Test
public void testBackup() throws Exception {
    val junitFolder = temporaryFolder.getRoot();
    val kylinConfig = KylinConfig.getInstanceFromEnv();
    kylinConfig.setProperty("kylin.env.hdfs-working-dir", junitFolder.getAbsolutePath());
    kylinConfig.setMetadataUrl("metadata_backup_ut_test");
    val resourceStore = ResourceStore.getKylinMetaStore(kylinConfig);
    if (!resourceStore.exists("/UUID")) {
        resourceStore.checkAndPutResource("/UUID", new StringEntity(RandomUtil.randomUUIDStr()), StringEntity.serializer);
    }
    //1.assert there is no metadata dir in root dir before backup,the root dir is junitFolder.getAbsolutePath()
    val rootPath = new Path(kylinConfig.getHdfsWorkingDirectory()).getParent();
    val rootFS = HadoopUtil.getWorkingFileSystem();
    Assertions.assertThat(rootFS.listStatus(rootPath)).isEmpty();
    //2.execute backup()
    var backupFolder = metadataBackupService.backupAll();
    //3.assert there is a metadata dir in root metadata dir after backup,
    // the metadata dir location is
    // junitFolder.getAbsolutePath()/metadata_backup_ut_test/backup/LocalDateTime/metadata
    val rootMetadataPath = new Path(kylinConfig.getHdfsWorkingDirectory() + "/_backup");
    val rootMetadataFS = HadoopUtil.getWorkingFileSystem();
    Assertions.assertThat(rootMetadataFS.listStatus(rootMetadataPath)).hasSize(1);
    val rootMetadataChildrenPath = rootMetadataFS.listStatus(rootMetadataPath)[0].getPath();
    Assertions.assertThat(rootMetadataChildrenPath.toUri().toString()).isEqualTo(backupFolder.getFirst());
    Assertions.assertThat(rootMetadataChildrenPath.getName()).isEqualTo(backupFolder.getSecond());
    val coreMetadataPath = new Path(rootMetadataChildrenPath, "core_meta");
    Assertions.assertThat(rootMetadataFS.listStatus(coreMetadataPath)).hasSize(2).contains(rootMetadataFS.getFileStatus(new Path(coreMetadataPath.toString() + File.separator + "UUID")), rootMetadataFS.getFileStatus(new Path(coreMetadataPath.toString() + File.separator + "_image")));
}

