@Test
public void testUpdateStatMeta() {
    QueryHistoryMetaUpdateScheduler taskScheduler = new QueryHistoryMetaUpdateScheduler("streaming_test");
    QueryHistoryMetaUpdateRunner metaUpdateRunner = taskScheduler.new QueryHistoryMetaUpdateRunner();
    NDataflowManager manager = NDataflowManager.getInstance(KylinConfig.getInstanceFromEnv(), "streaming_test");
    {
        var dataflow = manager.getDataflow("334671fd-e383-4fc9-b5c2-94fce832f77a");
        Assert.assertTrue(dataflow.getLayoutHitCount().isEmpty());
        ReflectionTestUtils.invokeMethod(metaUpdateRunner, "updateStatMeta", batchModelQueryHistory());
        dataflow = manager.getDataflow("334671fd-e383-4fc9-b5c2-94fce832f77a");
        Assert.assertEquals(1, countDateFrequency(dataflow, LAYOUT3));
    }
    {
        var batchDataflow = manager.getDataflow("334671fd-e383-4fc9-b5c2-94fce832f77a");
        var streamingDataflow = manager.getDataflow("b05034a8-c037-416b-aa26-9e6b4a41ee40");
        Assert.assertFalse(batchDataflow.getLayoutHitCount().containsKey(Long.parseLong(LAYOUT4)));
        Assert.assertFalse(streamingDataflow.getLayoutHitCount().containsKey(Long.parseLong(LAYOUT3)));
        ReflectionTestUtils.invokeMethod(metaUpdateRunner, "updateStatMeta", fusionModelQueryHistory());
        batchDataflow = manager.getDataflow("334671fd-e383-4fc9-b5c2-94fce832f77a");
        streamingDataflow = manager.getDataflow("b05034a8-c037-416b-aa26-9e6b4a41ee40");
        Assert.assertEquals(1, countDateFrequency(batchDataflow, LAYOUT4));
        Assert.assertEquals(1, countDateFrequency(streamingDataflow, LAYOUT3));
    }
    {
        var streamingDataflow = manager.getDataflow("b05034a8-c037-416b-aa26-9e6b4a41ee40");
        Assert.assertEquals(1, countDateFrequency(streamingDataflow, LAYOUT3));
        ReflectionTestUtils.invokeMethod(metaUpdateRunner, "updateStatMeta", streamingModelQueryHistory());
        streamingDataflow = manager.getDataflow("b05034a8-c037-416b-aa26-9e6b4a41ee40");
        Assert.assertEquals(2, countDateFrequency(streamingDataflow, LAYOUT3));
    }
}

@Test
public void testCreateUser() {
    getTestConfig().setProperty("kylin.security.acl.data-permission-default-enabled", "false");
    if (!userService.userExists("ADMIN1")) {
        userService.createUser(new ManagedUser("ADMIN1", "ADMIN1", false, //
        Arrays.//
        asList(new SimpleGrantedAuthority(Constant.ROLE_ADMIN))));
    }
    userAclService.deleteUserAcl("ADMIN1");
    userAclService.revokeUserAclPermission("ADMIN1", "DATA_QUERY");
    Assert.assertFalse(userAclService.hasUserAclPermission("ADMIN1", AclPermission.DATA_QUERY));
    userAclService.grantUserAclPermission("ADMIN1", "DATA_QUERY");
    Assert.assertTrue(userAclService.hasUserAclPermission("ADMIN1", AclPermission.DATA_QUERY));
    Assert.assertEquals(2, userAclService.listUserAcl().size());
    userAclService.revokeUserAclPermission("ADMIN1", "DATA_QUERY");
    Assert.assertFalse(userAclService.hasUserAclPermission("ADMIN1", AclPermission.DATA_QUERY));
    GlobalAccessRequest accessRequest = new GlobalAccessRequest();
    accessRequest.setUsername("ADMIN1");
    accessRequest.setProject("default");
    userAclService.addProjectToUserAcl(accessRequest, "DATA_QUERY");
    aclEvaluate.checkProjectQueryPermission("default");
    Assert.assertTrue(userAclService.hasUserAclPermissionInProject(accessRequest.getUsername(), accessRequest.getProject()));
    userAclService.deleteProjectFromUserAcl(accessRequest, "DATA_QUERY");
    Assert.assertFalse(userAclService.hasUserAclPermissionInProject(accessRequest.getUsername(), accessRequest.getProject()));
    ReflectionTestUtils.setField(userAclService, "userService", new KylinUserService() {

        public List<String> listSuperAdminUsers() {
            return Arrays.asList("ADMIN", "ADMIN1", "ADMIN2");
        }
    });
    Assert.assertEquals(3, userAclService.listUserAcl().size());
    Assert.assertTrue(userAclService.listUserAcl().get(0).getExtPermissions().contains("DATA_QUERY"));
    Assert.assertTrue(userAclService.listUserAcl().get(1).getExtPermissions().contains("DATA_QUERY"));
    Assert.assertTrue(userAclService.listUserAcl().get(2).getExtPermissions().contains("DATA_QUERY"));
    thrown.expect(KylinException.class);
    thrown.expectMessage(MsgPicker.getMsg().getModifyPermissionOfSuperAdminFailed());
    userAclService.grantUserAclPermission("admin", "DATA_QUERY");
}

