@OverwriteProp(key = "kylin.metadata.url", value = "test@jdbc,driverClassName=org.h2.Driver,url=jdbc:h2:mem:db_default;DB_CLOSE_DELAY=-1;MODE=MYSQL,username=sa,password=")
@Test
public void testAuditLogOutOfOrder() throws Exception {
    val listener = new StatusListener();
    val url = getTestConfig().getMetadataUrl();
    val table = url.getIdentifier();
    EventBusFactory.getInstance().register(listener, true);
    val systemStore = ResourceStore.getKylinMetaStore(getTestConfig());
    val jdbcTemplate = getJdbcTemplate();
    val auditLogStore = (JdbcAuditLogStore) systemStore.getAuditLogStore();
    val txManager = auditLogStore.getTransactionManager();
    UnitOfWork.doInTransactionWithRetry(() -> {
        val store = ResourceStore.getKylinMetaStore(KylinConfig.getInstanceFromEnv());
        MemoryLockUtils.lockAndRecord("/_global/project/p1.json", null, false);
        store.checkAndPutResource("/_global/project/p1.json", new StringEntity(RandomUtil.randomUUIDStr()), StringEntity.serializer);
        return null;
    }, "p1");
    UnitOfWork.doInTransactionWithRetry(() -> {
        val store = ResourceStore.getKylinMetaStore(KylinConfig.getInstanceFromEnv());
        MemoryLockUtils.lockAndRecord("/_global/project/p2.json", null, false);
        store.checkAndPutResource("/_global/project/p2.json", new StringEntity(RandomUtil.randomUUIDStr()), StringEntity.serializer);
        return null;
    }, "p2");
    Assert.assertEquals(2, systemStore.listResourcesRecursively("/").size());
    new Thread(() -> {
        val definition = new DefaultTransactionDefinition();
        definition.setIsolationLevel(TransactionDefinition.ISOLATION_READ_COMMITTED);
        val status = txManager.getTransaction(definition);
        val t1 = new Thread(() -> {
            UnitOfWork.doInTransactionWithRetry(() -> {
                Thread.sleep(500);
                val store = ResourceStore.getKylinMetaStore(KylinConfig.getInstanceFromEnv());
                val path = "/p1/abc-" + System.currentTimeMillis();
                MemoryLockUtils.lockAndRecord(path, null, false);
                val originAbc = store.getResource(path);
                store.checkAndPutResource(path, ByteSource.wrap("abc".getBytes(charset)), System.currentTimeMillis(), originAbc == null ? -1 : originAbc.getMvcc());
                return 0;
            }, "p1");
            try {
                auditLogStore.catchupWithTimeout();
            } catch (Exception e) {
                log.error("catchup 1st phase failed", e);
            }
        });
        t1.start();
        val unitId = RandomUtil.randomUUIDStr();
        Map<String, Long> versions = Maps.newHashMap();
        int size = 200;
        IntStream.range(1000, 1000 + size).forEach(id -> {
            String path = "/p2/abc" + id;
            long ts = System.currentTimeMillis();
            RawResource result = systemStore.getResource(path);
            val newMvcc = result == null ? 0 : result.getMvcc() + 1;
            if (newMvcc == 0) {
                jdbcTemplate.update(String.format(Locale.ROOT, INSERT_SQL, table), ps -> {
                    ps.setString(1, path);
                    ps.setBytes(2, path.getBytes(charset));
                    ps.setLong(3, ts);
                    ps.setLong(4, newMvcc);
                });
            } else {
                jdbcTemplate.update(String.format(Locale.ROOT, UPDATE_SQL, table), ps -> {
                    ps.setBytes(1, path.getBytes(charset));
                    ps.setLong(2, newMvcc);
                    ps.setLong(3, ts);
                    ps.setString(4, path);
                });
            }
            jdbcTemplate.update(String.format(Locale.ROOT, INSERT_AUDIT_LOG_SQL, table + "_audit_log"), ps -> {
                ps.setString(1, path);
                ps.setBytes(2, path.getBytes(charset));
                ps.setLong(3, ts);
                ps.setLong(4, newMvcc);
                ps.setString(5, unitId);
                ps.setString(6, null);
                ps.setString(7, "127.0.0.1:7072");
            });
            versions.put(path, newMvcc);
        });
        try {
            t1.join();
            Thread.sleep(1000);
        } catch (InterruptedException e) {
            log.debug("wait for thread join failed", e);
        }
        txManager.commit(status);
        try {
            auditLogStore.catchupWithTimeout();
        } catch (Exception e) {
            log.error("catchup 2nd phase failed", e);
        }
        UnitOfWork.doInTransactionWithRetry(() -> {
            val store = ResourceStore.getKylinMetaStore(KylinConfig.getInstanceFromEnv());
            IntStream.range(1000, 1000 + size).forEach(id -> {
                String path = "/p2/abc" + id;
                MemoryLockUtils.lockAndRecord(path, null, false);
                val originAbc = store.getResource(path);
                store.checkAndPutResource(path, ByteSource.wrap((path + "-version2").getBytes(charset)), System.currentTimeMillis(), originAbc == null ? -1 : originAbc.getMvcc());
            });
            return 0;
        }, "p2");
        try {
            auditLogStore.catchupWithTimeout();
        } catch (Exception e) {
            log.error("catchup 3rd phase failed", e);
        }
    }).start();
    Awaitility.await().atMost(200, TimeUnit.SECONDS).until(() -> listener.status == -1);
    Assert.assertEquals(203, systemStore.listResourcesRecursively("/").size());
}

