    byte[] contents = jdbcTemplate.queryForObject("select META_TABLE_CONTENT from " + tableName + " where META_TABLE_KEY = '/p1/test'", (rs, rowNum) -> rs.getBytes(1));
    Assert.assertTrue(CompressionUtils.isCompressed(contents));
    byte[] gzip = "GZIP".getBytes(StandardCharsets.UTF_8);
    Assert.assertArrayEquals(gzip, Arrays.copyOf(contents, gzip.length));
    Assert.assertArrayEquals("test content".getBytes(StandardCharsets.UTF_8), CompressionUtils.decompress(contents));
    byte[] auditLogContents = jdbcTemplate.queryForObject("select meta_content from " + tableName + "_audit_log where meta_key = '/p1/test'", (rs, rowNum) -> rs.getBytes(1));
    Assert.assertTrue(CompressionUtils.isCompressed(auditLogContents));
    Assert.assertArrayEquals(gzip, Arrays.copyOf(auditLogContents, gzip.length));
    Assert.assertArrayEquals("test content".getBytes(StandardCharsets.UTF_8), CompressionUtils.decompress(auditLogContents));
}

