@Test
void testReadLockExclusive() {
    val resourceStore = ResourceStore.getKylinMetaStore(KylinConfig.getInstanceFromEnv());
    resourceStore.checkAndPutResource("/_global/path/res1", ByteSource.wrap("{}".getBytes(Charset.defaultCharset())), -1L);
    Object condition = new Object();
    AtomicBoolean stop = new AtomicBoolean();
    Thread readLockHelder = new Thread(() -> {
        UnitOfWork.doInTransactionWithRetry(UnitOfWorkParams.builder().unitName(UnitOfWork.GLOBAL_UNIT).readonly(true).maxRetry(1).processor(() -> {
            ResourceStore.getKylinMetaStore(KylinConfig.getInstanceFromEnv()).getResource("/_global/path/res1");
            synchronized (condition) {
                condition.notify();
            }
            boolean interrupted = false;
            while (!interrupted && !Thread.interrupted() && !stop.get()) {
                synchronized (condition) {
                    condition.notify();
                }
                try {
                    Thread.sleep(1000);
                } catch (InterruptedException e) {
                    interrupted = true;
                }
            }
            return 0;
        }).build());
    });
    readLockHelder.start();
    synchronized (condition) {
        try {
            condition.wait();
        } catch (InterruptedException e) {
            e.printStackTrace();
        }
    }
    long readStart = System.currentTimeMillis();
    try {
        UnitOfWork.doInTransactionWithRetry(UnitOfWorkParams.builder().unitName(UnitOfWork.GLOBAL_UNIT).readonly(true).maxRetry(1).processor(() -> {
            long cost = System.currentTimeMillis() - readStart;
            Assertions.assertTrue(cost < 500);
            Assertions.assertEquals(0, ResourceStore.getKylinMetaStore(KylinConfig.getInstanceFromEnv()).getResource("/_global/path/res1").getMvcc());
            return 0;
        }).build());
    } catch (Exception e) {
        Assertions.fail();
    }
    new Thread(() -> {
        try {
            Thread.sleep(2000);
        } catch (InterruptedException e) {
            e.printStackTrace();
        }
        stop.set(true);
    }).start();
    long writeStart = System.currentTimeMillis();
    try {
        UnitOfWork.doInTransactionWithRetry(UnitOfWorkParams.builder().unitName(UnitOfWork.GLOBAL_UNIT).readonly(false).maxRetry(1).processor(() -> {
            MemoryLockUtils.lockAndRecord("/_global/path/res1", null, false);
            long cost = System.currentTimeMillis() - writeStart;
            Assertions.assertTrue(cost > 1500);
            Assertions.assertEquals(0, ResourceStore.getKylinMetaStore(KylinConfig.getInstanceFromEnv()).getResource("/_global/path/res1").getMvcc());
            return 0;
        }).build());
    } catch (Exception e) {
        Assertions.fail();
    }
    stop.set(true);
}

