    Mockito.when(entity.getDependencies()).thenReturn(dependencies);
    Mockito.when(cache.getIfPresent("mock")).thenReturn(entity);
    Mockito.when(store.getResource(resPath)).thenReturn(new RawResource(resPath, ByteSource.wrap("version1".getBytes(charset)), 0L, 0));
    Mockito.when(store.getResource(depPath1)).thenReturn(new RawResource(depPath1, ByteSource.wrap("version1".getBytes(charset)), 0L, 0));
    Mockito.when(store.getResource(depPath2)).thenReturn(new RawResource(depPath2, ByteSource.wrap("version1".getBytes(charset)), 0L, 0));
