    IndexPlan finalNewPlan = newPlan2;
    Assert.assertTrue(newPlan2.getAllLayouts().stream().noneMatch(l -> finalNewPlan.getRuleBasedIndex().getLayoutBlackList().contains(l.getId())));
}

