    //         layouts in index3 don't contain shardByColumns, they will not be reduced.
    Map<LayoutEntity, LayoutEntity> map2 = IndexPlanReduceUtil.collectIncludedLayouts(collectLayouts(tableIndex3, tableIndex4), true);
    Assert.assertTrue(map2.isEmpty());
}

