@Test
public void testIsDatatypeSuitable() {
    List<DataType> allDataTypes = Stream.of("short", "long", "int4", "long8", "byte", "binary", "numeric", "datetime", "time", "real", "any", "varchar", "char", "integer", "tinyint", "smallint", "bigint", "float", "decimal", "double", "array", "timestamp", "date", "string", "boolean", "int").map(DataType::getType).collect(Collectors.toList());
    List<String> allFunctions = Arrays.asList("SUM", "MIN", "MAX", "COUNT", "COLLECT_SET", "COUNT_DISTINCT", "PERCENTILE_APPROX", "TOP_N");
    Map<String, List<DataType>> funcSuitableDataTypeMap = new HashMap<>();
    funcSuitableDataTypeMap.put("SUM", Stream.of("tinyint", "smallint", "integer", "bigint", "float", "double", "decimal").map(DataType::getType).collect(Collectors.toList()));
    funcSuitableDataTypeMap.put("TOP_N", Stream.of("tinyint", "smallint", "integer", "bigint", "float", "double", "decimal").map(DataType::getType).collect(Collectors.toList()));
    funcSuitableDataTypeMap.put("PERCENTILE_APPROX", Stream.of("tinyint", "smallint", "integer", "bigint").map(DataType::getType).collect(Collectors.toList()));
    for (DataType dataType : allDataTypes) {
        for (String function : allFunctions) {
            FunctionDesc functionDesc = FunctionDesc.newInstance(function, newParameters(TblColRef.mockup(null, 0, "col", dataType.getName())), null);
            Assert.assertEquals(functionDesc.isDatatypeSuitable(dataType), funcSuitableDataTypeMap.getOrDefault(function, allDataTypes).contains(dataType));
        }
    }
}

