@Test
public void testQueryParseCaseSensitive() throws Throwable {
    KylinConfig config = KylinConfig.getInstanceFromEnv();
    config.setProperty("kylin.source.name-case-sensitive-enabled", "true");
    final String[] select_sqls = { "select count(1), TEST_ACCOUNT.account_buyer_level from TEST_KYLIN_FACT inner join TEST_ACCOUNT on TEST_KYLIN_FACT.SELLER_ID = TEST_ACCOUNT.ACCOUNT_ID group by TEST_ACCOUNT.account_buyer_level", "select count(1), TEST_ACCOUNT.ACCOUNT_BUYER_LEVEL from TEST_KYLIN_FACT inner join TEST_ACCOUNT on TEST_KYLIN_FACT.SELLER_ID = TEST_ACCOUNT.ACCOUNT_ID group by TEST_ACCOUNT.ACCOUNT_BUYER_LEVEL" };
    final String[] select_columns = { "account_buyer_level", "ACCOUNT_BUYER_LEVEL" };
