    runningJobs.add(job1);
    runningJobs.add(job2);
    result = thread.checkNeedBuildPartitionAndSetTableOption(req, runningJobs);
    assertTrue(result);
    runningJobs.remove(job2);
    result = thread.checkNeedBuildPartitionAndSetTableOption(req, runningJobs);
    assertFalse(result);
    assertEquals(1, req.size());
    val options = ((HashMap) req.get("options"));
