        Assert.assertTrue(e instanceof KylinException);
        Assert.assertEquals(SEGMENT_MERGE_CHECK_INDEX_ILLEGAL.getMsg(), e.getMessage());
    }
    // partitions are not aligned in segment2, segment3
    try {
        modelBuildService.mergeSegmentsManually(new MergeSegmentParams(project, modelId, new String[] { dataSegment2.getId(), dataSegment3.getId() }));
        Assert.fail();
    } catch (Exception e) {
        Assert.assertTrue(e instanceof KylinException);
        Assert.assertEquals(SEGMENT_MERGE_CHECK_PARTITION_ILLEGAL.getMsg(), e.getMessage());
    }
    // success
    modelBuildService.mergeSegmentsManually(new MergeSegmentParams(project, modelId, new String[] { dataSegment1.getId(), dataSegment2.getId() }));
