    val tableMetadataManager = NTableMetadataManager.getInstance(getTestConfig(), PROJECT);
    val tableExt = tableMetadataManager.getOrCreateTableExt(table);
    val copyForWrite = tableMetadataManager.copyForWrite(tableExt);
