    Assert.assertEquals("SELECT CAST(\"BYTE\" AS VARCHAR(1024))\nFROM \"DEFAULT\".\"FACT\"", converter.convertSql("select cast(BYTE as VARCHAR(1024)) from \"DEFAULT\".FACT"));
    // cannot find mapping
    Assert.assertEquals("SELECT \"CURRENT_DATE_1\", \"CURRENT_TIME_1\"", converter.convertSql("select CURRENT_DATE_1, CURRENT_TIME_1"));
    Assert.assertEquals("SELECT \"CURRENT_DATE_1\", TEST_CURR_TIME(), \"CURRENT_DATE\"", converter.convertSql("select CURRENT_DATE_1, CURRENT_TIME, CURRENT_DATE"));
    Assert.assertEquals("SELECT CAST(\"BYTE\" AS VAR(1024))\nFROM \"DEFAULT\".\"FACT\"", converter.convertSql("select cast(BYTE as VAR(1024)) from \"DEFAULT\".FACT"));
    Assert.assertEquals("SELECT CAST(\"PRICE\" AS DDD)\nFROM \"DEFAULT\".\"FACT\"", converter.convertSql("select cast(PRICE as DDD) from \"DEFAULT\".FACT"));
    Assert.assertEquals("SELECT A(), B(\"A\"), CAST(\"PRICE\" AS DDD)\nFROM \"DEFAULT\".\"FACT\"", converter.convertSql("select A(), B(A), cast(PRICE as DDD) from \"DEFAULT\".\"FACT\""));
    Assert.assertEquals("SELECT ONLY_DEFAULT(1)", converter.convertSql("SELECT ONLY_DEFAULT(1)"));
    // invalid case
    Assert.assertEquals("create table test(id int, price double, name string, value byte)", converter.convertSql("create table test(id int, price double, name string, value byte)"));
    Assert.assertEquals("select cast(BYTE as VARCHAR(1000000000000)) from \"DEFAULT\".FACT", converter.convertSql("select cast(BYTE as VARCHAR(1000000000000)) from \"DEFAULT\".FACT"));
    Assert.assertEquals("I am not a SQL", converter.convertSql("I am not a SQL"));
}

