    // date type column need to convert with defined Date pattern
    Assert.assertEquals("TO_CHAR(\"TEST\".\"AA\", 'xxxxx')", converter.formatDateColumn("test.aa", new DataType("timestamp", 0, 0), "xxxxx"));
    // non date type column
    Assert.assertEquals("\"TEST\".\"AA\"", converter.formatDateColumn("test.aa", new DataType("interger", 0, 0), ""));
    // date type column need to convert but without pattern, use format defined
    Assert.assertEquals("SELECT \"AA\"\nFROM \"TABLEAA\" WHERE TO_CHAR(\"AA\", 'YYYY-MM-DD HH:mm:ss') < '2019-01-01'", converter.convertDateCondition("select aa from tableaa where aa < '2019-01-01'", "AA", new DataType("timestamp", 0, 0), ""));
    // date type column need to convert with defined Date pattern
    Assert.assertEquals("SELECT \"AA\"\nFROM \"TABLEAA\" WHERE TO_CHAR(\"AA\", 'xxxxx') < '2019-01-01'", converter.convertDateCondition("select aa from tableaa where aa < '2019-01-01'", "AA", new DataType("timestamp", 0, 0), "xxxxx"));
