    assertEquals(1, KylinCheckSql.countDynamicPlaceholder(sql4));
    assertEquals(1, KylinCheckSql.countDynamicPlaceholder(sql5));
    assertEquals(1, KylinCheckSql.countDynamicPlaceholder(sql6));
}

