    overwriteSystemProp("kylin.storage.columnar.shard-rowcount", "100");
    fullBuild("8c670664-8d05-466a-802f-83c023b56c77");
    populateSSWithCSVData(getTestConfig(), getProject(), SparderEnv.getSparkSession());
    SparkPlan sparkPlan;
    AtomicLong accumRowsCounter;
    val sql1 = "select * from " + "(select TRANS_ID,LSTG_FORMAT_NAME from TEST_KYLIN_FACT group by TRANS_ID,LSTG_FORMAT_NAME) lside left join " + "(select TRANS_ID,LSTG_FORMAT_NAME from TEST_KYLIN_FACT group by TRANS_ID,LSTG_FORMAT_NAME) rside " + "on lside.TRANS_ID = rside.TRANS_ID limit 10";
    sparkPlan = getSparkExecutedPlan(sql1);
    accumRowsCounter = new AtomicLong();
    ResultPlan.extractEachStageLimitRows(sparkPlan, -1, accumRowsCounter);
    Assert.assertEquals(10010, accumRowsCounter.get());
    val sql2 = "select TRANS_ID,LSTG_FORMAT_NAME from TEST_KYLIN_FACT group by TRANS_ID,LSTG_FORMAT_NAME limit 10";
    sparkPlan = getSparkExecutedPlan(sql2);
    accumRowsCounter = new AtomicLong();
    ResultPlan.extractEachStageLimitRows(sparkPlan, -1, accumRowsCounter);
    Assert.assertEquals(10, accumRowsCounter.get());
    val sql3 = "select count(*) from (select TRANS_ID,LSTG_FORMAT_NAME from TEST_KYLIN_FACT group by TRANS_ID,LSTG_FORMAT_NAME limit 10)";
    sparkPlan = getSparkExecutedPlan(sql3);
    accumRowsCounter = new AtomicLong();
    ResultPlan.extractEachStageLimitRows(sparkPlan, -1, accumRowsCounter);
    Assert.assertEquals(10, accumRowsCounter.get());
}

@Test
public void unwrapComputeColumn() {
    val dataModelManager = NDataModelManager.getInstance(KylinConfig.getInstanceFromEnv(), "cc_test");
    var dataModelDesc = dataModelManager.getDataModelDesc("4a45dc4d-937e-43cc-8faa-34d59d4e11d3");
    var computedColumn = dataModelDesc.getEffectiveCols().values().stream().filter(tblColRef -> tblColRef.getColumnDesc().getName().equals("CC_NUM")).findAny().get();
    IndexDependencyParser parser = new IndexDependencyParser(dataModelDesc);
    Assert.assertNotNull(computedColumn);
    Assert.assertTrue(computedColumn.getColumnDesc().isComputedColumn());
    // 1+2
    Set<TblColRef> tblColRefList = parser.unwrapComputeColumn(computedColumn.getExpressionInSourceDB());
    Assert.assertEquals(0, tblColRefList.size());
    computedColumn = dataModelDesc.getEffectiveCols().values().stream().filter(tblColRef -> tblColRef.getColumnDesc().getName().equals("CC_LTAX")).findAny().get();
    // `LINEORDER`.`LO_TAX` +1
    tblColRefList = parser.unwrapComputeColumn(computedColumn.getExpressionInSourceDB());
    Assert.assertEquals(1, tblColRefList.size());
    Assert.assertTrue(tblColRefList.stream().anyMatch(tblColRef -> "LINEORDER.LO_TAX".equals(tblColRef.getIdentity())));
    dataModelDesc = dataModelManager.getDataModelDesc("0d146f1a-bdd3-4548-87ac-21c2c6f9a0da");
    computedColumn = dataModelDesc.getEffectiveCols().values().stream().filter(tblColRef -> tblColRef.getColumnDesc().getName().equals("CC_TOTAL_TAX")).findAny().get();
    Assert.assertTrue(computedColumn.getColumnDesc().isComputedColumn());
    // LINEORDER.LO_QUANTITY*LINEORDER.LO_TAX
    tblColRefList = parser.unwrapComputeColumn(computedColumn.getExpressionInSourceDB());
    Assert.assertEquals(2, tblColRefList.size());
    Assert.assertTrue(tblColRefList.stream().anyMatch(tblColRef -> tblColRef.getIdentity().equals("LINEORDER.LO_QUANTITY")));
    Assert.assertTrue(tblColRefList.stream().anyMatch(tblColRef -> tblColRef.getIdentity().equals("LINEORDER.LO_TAX")));
    computedColumn = dataModelDesc.getAllTableRefs().stream().filter(tableRef -> tableRef.getTableIdentity().equals("SSB.LINEORDER")).map(TableRef::getColumns).flatMap(Collection::stream).filter(tblColRef -> tblColRef.getColumnDesc().getName().equals("CC_EXTRACT")).findAny().get();
    Assert.assertTrue(computedColumn.getColumnDesc().isComputedColumn());
    // MINUTE(`LINEORDER`.`LO_ORDERDATE`)
    tblColRefList = parser.unwrapComputeColumn(computedColumn.getExpressionInSourceDB());
    Assert.assertEquals(1, tblColRefList.size());
    Assert.assertTrue(tblColRefList.stream().anyMatch(tblColRef -> tblColRef.getIdentity().equals("LINEORDER.LO_ORDERDATE")));
    computedColumn = dataModelDesc.getAllTableRefs().stream().filter(tableRef -> tableRef.getTableIdentity().equals("SSB.LINEORDER")).map(TableRef::getColumns).flatMap(Collection::stream).filter(tblColRef -> tblColRef.getColumnDesc().getName().equals("CC_CAST_LO_ORDERKEY")).findAny().get();
    Assert.assertTrue(computedColumn.getColumnDesc().isComputedColumn());
    // cast(`lineorder`.`lo_orderkey` as double)
    tblColRefList = parser.unwrapComputeColumn(computedColumn.getExpressionInSourceDB());
    Assert.assertEquals(1, tblColRefList.size());
    Assert.assertTrue(tblColRefList.stream().anyMatch(tblColRef -> tblColRef.getIdentity().equals("LINEORDER.LO_ORDERKEY")));
}

