@Test
public void testHeterogeneousSegmentFilters() throws SqlParseException {
    // layout 20000000001, tableindex
    // layout 20001, cal_dt & trans_id
    // layout 10001, cal_dt
    // layout 1, trans_id
    // segment1 [2012-01-01, 2012-01-02] layout 20000000001, 20001
    // segment2 [2012-01-02, 2012-01-03] layout 20000000001, 20001, 10001
    // segment3 [2012-01-03, 2012-01-04] layout 20001, 10001, 1
    // segment4 [2012-01-04, 2012-01-05] layout 10001, 1
    // segment5 [2012-01-05, 2012-01-06] layout 20000000001, 20001, 10001, 1
    val project = "heterogeneous_segment";
    val sql = "with T1 as (select cal_dt, trans_id \n" + "from test_kylin_fact inner join test_account \n" + "on test_kylin_fact.seller_id = test_account.account_id \n" + "where cal_dt between date'2012-01-01' and date'2012-01-03'\n" + "group by cal_dt, trans_id)\n";
    {
        // composite filters
        val sqlFilter = sql + "select * from T1\n" + "where (cal_dt = DATE'2012-01-01' or (cast(cal_dt as date) = '2012-01-02' or cal_dt = '2012-01-03')) and (cal_dt is not null or cal_dt in ('2012-01-01', '2012-01-02'))";
        val context = OlapContextTestUtil.getOlapContexts(project, sqlFilter).get(0);
        assertFiltersAndLayout(context, null, ">=(DEFAULT.TEST_KYLIN_FACT.CAL_DT, 2012-01-01),<=(DEFAULT.TEST_KYLIN_FACT.CAL_DT, 2012-01-03)," + "OR(=(DEFAULT.TEST_KYLIN_FACT.CAL_DT, 2012-01-01), =(DEFAULT.TEST_KYLIN_FACT.CAL_DT, 2012-01-02), =(DEFAULT.TEST_KYLIN_FACT.CAL_DT, 2012-01-03))," + "OR(IS NOT NULL(DEFAULT.TEST_KYLIN_FACT.CAL_DT), OR(=(DEFAULT.TEST_KYLIN_FACT.CAL_DT, 2012-01-01), =(DEFAULT.TEST_KYLIN_FACT.CAL_DT, 2012-01-02)))");
    }
    {
        // invalid filters with or
        val sqlFilter = sql + "select * from T1\n" + "where trans_id = 123  or trans_id + 1 = 123 or (trans_id + 2 = 234 and trans_id = 345)";
        val context = OlapContextTestUtil.getOlapContexts(project, sqlFilter).get(0);
        assertFiltersAndLayout(context, null, ">=(DEFAULT.TEST_KYLIN_FACT.CAL_DT, 2012-01-01),<=(DEFAULT.TEST_KYLIN_FACT.CAL_DT, 2012-01-03)");
    }
    {
        // invalid filters with and
        val sqlFilter = sql + "select * from T1\n" + "where trans_id = 123 and (trans_id + 2 = 234 or trans_id = 345)";
        val context = OlapContextTestUtil.getOlapContexts(project, sqlFilter).get(0);
        assertFiltersAndLayout(context, null, ">=(DEFAULT.TEST_KYLIN_FACT.CAL_DT, 2012-01-01),<=(DEFAULT.TEST_KYLIN_FACT.CAL_DT, 2012-01-03)," + "=(DEFAULT.TEST_KYLIN_FACT.TRANS_ID, 123)");
    }
    {
        // invalid filters with not
        val sqlFilter = sql + "select * from T1\n" + "where trans_id = 123 and (not(trans_id = 234) or trans_id = 345) and (not(trans_id + 1 = 132))";
        val context = OlapContextTestUtil.getOlapContexts(project, sqlFilter).get(0);
        assertFiltersAndLayout(context, null, ">=(DEFAULT.TEST_KYLIN_FACT.CAL_DT, 2012-01-01),<=(DEFAULT.TEST_KYLIN_FACT.CAL_DT, 2012-01-03)," + "=(DEFAULT.TEST_KYLIN_FACT.TRANS_ID, 123),OR(<>(DEFAULT.TEST_KYLIN_FACT.TRANS_ID, 234), =(DEFAULT.TEST_KYLIN_FACT.TRANS_ID, 345))");
    }
}

