    for (NDataSegment segment : df2.getSegments()) {
        for (Map.Entry<Long, NDataLayout> entry : segment.getLayoutsMap().entrySet()) {
            expected.add(root + df2.getId() + "/" + segment.getId() + "/" + entry.getKey());
