    } catch (Exception e) {
        Assert.assertTrue(e instanceof KylinException);
        Assert.assertEquals(PROJECT_MULTI_PARTITION_DISABLE.getCodeMsg("TEST_PROJECT_NAME"), e.getLocalizedMessage());
    }
}

