    JsonUtil.writeValueAsString(request2)).accept(//
    MediaType.parseMediaType(HTTP_VND_APACHE_KYLIN_V4_PUBLIC_JSON))).andExpect(MockMvcResultMatchers.status().isOk());
    Mockito.verify(openTableController).reloadAWSTablesCompatibleCrossAccount(request2);
}

@Test
public void testPrepareUnloadTable() throws Exception {
    {
        Mockito.doReturn(new PreUnloadTableResponse()).when(tableService).preUnloadTable("default", "DEFAULT.TABLE");
        mockMvc.perform(MockMvcRequestBuilders.get("/api/tables/{database}/{table}/prepare_unload", "DEFAULT", "TABLE").param("project", "default").accept(MediaType.parseMediaType(HTTP_VND_APACHE_KYLIN_V4_PUBLIC_JSON))).andExpect(MockMvcResultMatchers.status().isOk());
        Mockito.verify(openTableController).prepareUnloadTable("default", "DEFAULT", "TABLE");
        Mockito.reset(tableService);
    }
    {
        // test case-insensitive
        String tableNameMixture = "TEsT_KYliNFAct";
        String tableNameLowerCase = "test_kylinfact";
        String tableNameUppercase = "TEST_KYLINFACT";
        String databaseMixture = "Ssb";
        String databaseLowercase = "ssb";
        String databaseUppercase = "SSB";
        mockMvc.perform(MockMvcRequestBuilders.get("/api/tables/{database}/{table}/prepare_unload", databaseMixture, tableNameMixture).param("project", "default").accept(MediaType.parseMediaType(HTTP_VND_APACHE_KYLIN_V4_PUBLIC_JSON))).andExpect(MockMvcResultMatchers.status().isOk());
        Mockito.verify(tableService, Mockito.times(1)).preUnloadTable("default", databaseUppercase + "." + tableNameUppercase);
        mockMvc.perform(MockMvcRequestBuilders.get("/api/tables/{database}/{table}/prepare_unload", databaseLowercase, tableNameLowerCase).param("project", "default").accept(MediaType.parseMediaType(HTTP_VND_APACHE_KYLIN_V4_PUBLIC_JSON))).andExpect(MockMvcResultMatchers.status().isOk());
        Mockito.verify(tableService, Mockito.times(2)).preUnloadTable("default", databaseUppercase + "." + tableNameUppercase);
        mockMvc.perform(MockMvcRequestBuilders.get("/api/tables/{database}/{table}/prepare_unload", databaseUppercase, tableNameUppercase).param("project", "default").accept(MediaType.parseMediaType(HTTP_VND_APACHE_KYLIN_V4_PUBLIC_JSON))).andExpect(MockMvcResultMatchers.status().isOk());
        Mockito.verify(tableService, Mockito.times(3)).preUnloadTable("default", databaseUppercase + "." + tableNameUppercase);
    }
}

