public void testUpdateRuleBasedSortDimension() {
    String modelId = "89af4ee2-2cdb-4b07-b39e-4c29856309aa";
    val aggregationGroup1 = new NAggregationGroup();
    aggregationGroup1.setIncludes(new Integer[] { 1, 2, 3, 4 });
