    val modelId = "89af4ee2-2cdb-4b07-b39e-4c29856309aa";
    val clean = prepare(modelId);
    val indexPlanManager = NIndexPlanManager.getInstance(KylinConfig.getInstanceFromEnv(), "default");
    val origin = indexPlanManager.getIndexPlan(modelId);
    val originLayoutSize = origin.getAllLayouts().size();
    var response = indexPlanService.createTableIndex("default", CreateTableIndexRequest.builder().project("default").modelId("89af4ee2-2cdb-4b07-b39e-4c29856309aa").colOrder(Arrays.asList("TEST_KYLIN_FACT.TRANS_ID", "TEST_KYLIN_FACT.CAL_DT", "TEST_KYLIN_FACT.LSTG_FORMAT_NAME", "TEST_KYLIN_FACT.LSTG_SITE_ID")).shardByColumns(Arrays.asList("TEST_KYLIN_FACT.TRANS_ID")).isLoadData(true).layoutOverrideIndexes(new HashMap<String, String>() {

        {
            put("TEST_KYLIN_FACT.LSTG_FORMAT_NAME", "eq");
        }
    }).sortByColumns(Arrays.asList("TEST_KYLIN_FACT.CAL_DT")).build(), 20000040000L);
    Assert.assertEquals(BuildIndexResponse.BuildIndexType.NORM_BUILD, response.getType());
    val saved = indexPlanManager.getIndexPlan("89af4ee2-2cdb-4b07-b39e-4c29856309aa");
    Assert.assertEquals(originLayoutSize + 1, saved.getAllLayouts().size());
    LayoutEntity newLayout = null;
    for (LayoutEntity layout : saved.getAllLayouts()) {
        if (newLayout == null) {
            newLayout = layout;
        } else {
            if (newLayout.getId() < layout.getId()) {
                newLayout = layout;
            }
        }
    }
    Assert.assertThat(newLayout.getColOrder(), CoreMatchers.is(Arrays.asList(1, 2, 3, 4)));
    Assert.assertThat(newLayout.getShardByColumns(), CoreMatchers.is(Arrays.asList(1)));
    Assert.assertThat(newLayout.getSortByColumns(), CoreMatchers.is(Arrays.asList()));
    indexPlanService.updateTableIndex("default", CreateTableIndexRequest.builder().id(20000040000L).project("default").modelId("89af4ee2-2cdb-4b07-b39e-4c29856309aa").colOrder(Arrays.asList("TEST_KYLIN_FACT.TRANS_ID", "TEST_KYLIN_FACT.CAL_DT", "TEST_KYLIN_FACT.LSTG_FORMAT_NAME", "TEST_KYLIN_FACT.LSTG_SITE_ID")).shardByColumns(Arrays.asList("TEST_KYLIN_FACT.CAL_DT")).sortByColumns(Arrays.asList("TEST_KYLIN_FACT.TRANS_ID")).build());
    Assert.assertFalse(indexPlanService.getManager(NIndexPlanManager.class, "default").getIndexPlan("89af4ee2-2cdb-4b07-b39e-4c29856309aa").getAllLayouts().stream().anyMatch(l -> l.getId() == 20000040000L));
    Assert.assertTrue(indexPlanService.getManager(NIndexPlanManager.class, "default").getIndexPlan("89af4ee2-2cdb-4b07-b39e-4c29856309aa").getAllLayouts().stream().anyMatch(l -> l.getId() == 20000040000L + IndexEntity.INDEX_ID_STEP));
}

@Test
public void testCreateTableIndexIsAuto() {
    val indexPlanManager = NIndexPlanManager.getInstance(KylinConfig.getInstanceFromEnv(), "default");
    val origin = indexPlanManager.getIndexPlan("89af4ee2-2cdb-4b07-b39e-4c29856309aa");
    val originLayoutSize = origin.getAllLayouts().size();
    indexPlanService.createTableIndex("default", CreateTableIndexRequest.builder().project("default").modelId("89af4ee2-2cdb-4b07-b39e-4c29856309aa").colOrder(Arrays.asList("TEST_KYLIN_FACT.TRANS_ID", "TEST_SITES.SITE_NAME", "TEST_KYLIN_FACT.CAL_DT", "TEST_KYLIN_FACT.LSTG_SITE_ID", "TEST_KYLIN_FACT.PRICE")).sortByColumns(Arrays.asList("TEST_SITES.SITE_NAME")).build());
    var saved = indexPlanManager.getIndexPlan("89af4ee2-2cdb-4b07-b39e-4c29856309aa");
    Assert.assertEquals(originLayoutSize, saved.getAllLayouts().size());
    var layout = saved.getLayoutEntity(20000000001L);
    Assert.assertTrue(layout.isManual());
    Assert.assertTrue(layout.isAuto());
    val executables = getRunningExecutables("default", "89af4ee2-2cdb-4b07-b39e-4c29856309aa");
    Assert.assertEquals(0, executables.size());
    indexPlanService.removeTableIndex("default", "89af4ee2-2cdb-4b07-b39e-4c29856309aa", 20000000001L);
    saved = indexPlanManager.getIndexPlan("89af4ee2-2cdb-4b07-b39e-4c29856309aa");
    layout = saved.getLayoutEntity(20000000001L);
    Assert.assertEquals(originLayoutSize, saved.getAllLayouts().size());
    Assert.assertFalse(layout.isManual());
    Assert.assertTrue(layout.isAuto());
}

