@Test
public void testCheckModelMetadataModelIndex() throws IOException {
    val file = new File("src/test/resources/ut_model_metadata/metastore_model_metadata_c4a20039c16dfbb5dcc5610c5052d7b3.zip");
    val multipartFile = new MockMultipartFile(file.getName(), file.getName(), null, Files.newInputStream(file.toPath()));
    val metadataCheckResponse = metaStoreService.checkModelMetadata("original_project", multipartFile, null);
    SchemaChangeCheckResult.ModelSchemaChange modelSchemaChange = metadataCheckResponse.getModels().get("model_index");
    Assert.assertNotNull(modelSchemaChange);
    Assert.assertEquals(3, modelSchemaChange.getDifferences());
    Assert.assertTrue(modelSchemaChange.getReduceItems().stream().filter(sc -> sc.getType() == SchemaNodeType.WHITE_LIST_INDEX).filter(sc -> sc.getDetail().equals("20000000001")).filter(SchemaChangeCheckResult.BaseItem::isOverwritable).anyMatch(sc -> {
        String col_orders = String.join(",", ((List<String>) sc.getAttributes().get("col_orders")));
        return col_orders.equals("P_LINEORDER.LO_CUSTKEY,P_LINEORDER.LO_SUPPKEY,P_LINEORDER.LO_ORDERDATE,P_LINEORDER.LO_QUANTITY,P_LINEORDER.LO_DISCOUNT,P_LINEORDER.LO_LINENUMBER,P_LINEORDER.LO_PARTKEY,P_LINEORDER.LO_ORDERKEY");
    }));
    Assert.assertTrue(modelSchemaChange.getNewItems().stream().filter(sc -> sc.getType() == SchemaNodeType.WHITE_LIST_INDEX).filter(sc -> sc.getDetail().equals("20000000001")).filter(SchemaChangeCheckResult.BaseItem::isOverwritable).anyMatch(sc -> {
        String col_orders = String.join(",", ((List<String>) sc.getAttributes().get("col_orders")));
        return col_orders.equals("P_LINEORDER.LO_LINENUMBER,P_LINEORDER.LO_SUPPKEY,P_LINEORDER.LO_QUANTITY,P_LINEORDER.LO_PARTKEY,P_LINEORDER.LO_ORDERKEY,P_LINEORDER.LO_CUSTKEY,P_LINEORDER.LO_DISCOUNT,P_LINEORDER.LO_ORDERDATE");
    }));
    Assert.assertTrue(modelSchemaChange.getNewItems().stream().filter(sc -> sc.getType() == SchemaNodeType.WHITE_LIST_INDEX).filter(sc -> sc.getDetail().equals("20000010001")).filter(SchemaChangeCheckResult.BaseItem::isOverwritable).anyMatch(sc -> {
        String col_orders = String.join(",", ((List<String>) sc.getAttributes().get("col_orders")));
        return col_orders.equals("P_LINEORDER.LO_SUPPKEY,P_LINEORDER.LO_QUANTITY");
    }));
}

