@Test
public void testImportModelMetadataWithMultiplePartitionValue() throws Exception {
    KylinConfig testConfig = getTestConfig();
    File file = new File("src/test/resources/ut_meta/schema_utils/model_different_multiple_partition_with_partition_value_reduce_project/target_project_model_metadata_2020_12_02_20_50_10_DAEEA810EA44E80BD3FA70CFE6AB1CAA.zip");
    var multipartFile = new MockMultipartFile(file.getName(), file.getName(), null, new FileInputStream(file));
    NDataModelManager dataModelManager = NDataModelManager.getInstance(testConfig, "original_project");
    NDataModel dataModel = dataModelManager.getDataModelDescByAlias("conflict_multiple_partition_col_model");
    MultiPartitionKeyMappingImpl originalMultiPartitionKeyMapping = dataModel.getMultiPartitionKeyMapping();
    MultiPartitionDesc originalMultiPartitionDesc = dataModel.getMultiPartitionDesc();
    Assert.assertEquals(Collections.singletonList("SSB.CUSTOMER.C_CUSTKEY"), originalMultiPartitionKeyMapping.getAliasCols());
    Assert.assertEquals(Collections.singletonList("SSB.P_LINEORDER.LO_CUSTKEY"), originalMultiPartitionKeyMapping.getMultiPartitionCols());
    Assert.assertEquals(Arrays.asList(Pair.newPair(Collections.singletonList("p1"), Collections.singletonList("p11")), Pair.newPair(Collections.singletonList("p2"), Collections.singletonList("p12")), Pair.newPair(Collections.singletonList("p3"), Collections.singletonList("p13"))), originalMultiPartitionKeyMapping.getValueMapping());
    Assert.assertEquals(Collections.singletonList("P_LINEORDER.LO_CUSTKEY"), originalMultiPartitionDesc.getColumns());
    Assert.assertEquals(Arrays.asList(new MultiPartitionDesc.PartitionInfo(0, new String[] { "p1" }), new MultiPartitionDesc.PartitionInfo(1, new String[] { "p2" }), new MultiPartitionDesc.PartitionInfo(3, new String[] { "p3" })), originalMultiPartitionDesc.getPartitions());
    ModelImportRequest request = new ModelImportRequest();
    List<ModelImportRequest.ModelImport> models = new ArrayList<>();
    models.add(new ModelImportRequest.ModelImport("conflict_multiple_partition_col_model", "conflict_multiple_partition_col_model", ModelImportRequest.ImportType.OVERWRITE));
    request.setModels(models);
    metaStoreService.importModelMetadata("original_project", multipartFile, request);
    KylinConfig kylinConfig = KylinConfig.createKylinConfig(KylinConfig.getInstanceFromEnv());
    dataModelManager = NDataModelManager.getInstance(kylinConfig, "original_project");
    dataModel = dataModelManager.getDataModelDescByAlias("conflict_multiple_partition_col_model");
    val targetMultiPartitionKeyMapping = dataModel.getMultiPartitionKeyMapping();
    val targetMultiPartitionDesc = dataModel.getMultiPartitionDesc();
    Assert.assertNull(targetMultiPartitionKeyMapping);
    Assert.assertEquals(Collections.singletonList("P_LINEORDER.LO_CUSTKEY"), targetMultiPartitionDesc.getColumns());
    Assert.assertEquals(Arrays.asList(new MultiPartitionDesc.PartitionInfo(1, new String[] { "p2" }), new MultiPartitionDesc.PartitionInfo(3, new String[] { "p3" })), targetMultiPartitionDesc.getPartitions());
}

