    IndicesResponse indices = modelService.getAggIndices("default", "89af4ee2-2cdb-4b07-b39e-4c29856309aa", null, null, false, 0, 10, null, true);
    Assert.assertEquals(5, indices.getIndices().size());
    Assert.assertTrue(indices.getIndices().get(0).getId() < IndexEntity.TABLE_INDEX_START_ID);
    final String contentSegIndexId = "200";
    indices = modelService.getAggIndices("default", "89af4ee2-2cdb-4b07-b39e-4c29856309aa", null, contentSegIndexId, false, 0, 10, null, true);
    Assert.assertTrue(indices.getIndices().stream().allMatch(index -> String.valueOf(index.getId()).contains(contentSegIndexId)));
    final String contentSegDimension = "ORDer";
    indices = modelService.getAggIndices("default", "89af4ee2-2cdb-4b07-b39e-4c29856309aa", null, contentSegDimension, false, 0, 10, null, true);
    Assert.assertTrue(indices.getIndices().stream().allMatch(index -> index.getDimensions().stream().anyMatch(d -> d.contains(contentSegDimension.toUpperCase(Locale.ROOT)))));
    final String contentSegMeasure = "GMV";
    indices = modelService.getAggIndices("default", "89af4ee2-2cdb-4b07-b39e-4c29856309aa", null, contentSegMeasure, true, 0, 10, null, true);
    Assert.assertTrue(indices.getIndices().stream().allMatch(index -> index.getMeasures().stream().anyMatch(d -> d.contains(contentSegMeasure))));
    indices = modelService.getAggIndices("default", "89af4ee2-2cdb-4b07-b39e-4c29856309aa", null, null, true, 0, 3, null, true);
    Assert.assertEquals(5, indices.getSize());
    Assert.assertEquals(3, indices.getIndices().size());
}

