@Test
void testDerivedFromSameContext() throws SqlParseException {
    val kylinConfig = getTestConfig();
    val config = KECalciteConfig.fromKapConfig(kylinConfig);
    String prj = "default";
    val schemaFactory = new ProjectSchemaFactory(prj, kylinConfig);
    val rootSchema = schemaFactory.createProjectRootSchema();
    String defaultSchemaName = schemaFactory.getDefaultSchema();
    val catalogReader = createCatalogReader(config, rootSchema, defaultSchemaName);
    val planner = new PlannerFactory(kylinConfig).createVolcanoPlanner(config);
    SimpleDataContext dataContext = new SimpleDataContext(rootSchema.plus(), TypeSystem.javaTypeFactory(), kylinConfig);
    planner.setExecutor(new RexExecutorImpl(dataContext));
    val sqlConverter = SQLConverter.createConverter(config, planner, catalogReader);
    val queryOptimizer = new QueryOptimizer(planner);
    RelRoot relRoot = sqlConverter.convertSqlToRelNode("SELECT count(1)\n" + "FROM \"SSB\".\"LINEORDER\" \"LINEORDER\"\n" + "JOIN (SELECT MAX(\"LINEORDER\".\"LO_ORDERDATE\") AS \"X_measure__0\"\n" + "FROM \"SSB\".\"LINEORDER\" \"LINEORDER\"\n" + "GROUP BY 1.1000000000000001 ) \"t0\"\n" + "ON LINEORDER.LO_ORDERDATE = t0.X_measure__0\n" + "GROUP BY 1.1000000000000001");
    RelNode node = queryOptimizer.optimize(relRoot).rel;
    val olapContexts = QueryContextCutter.selectRealization(prj, node, BackdoorToggles.getIsQueryFromAutoModeling());
    Assertions.assertNotNull(olapContexts);
    Assertions.assertFalse(olapContexts.isEmpty());
}

@Test
public void testQueryRouteWithSecondStorage() {
    ThrowExceptionAtFirstTime throwExceptionAtFirstTime = new ThrowExceptionAtFirstTime(true);
    ThrownExceptionEngine engine = new ThrownExceptionEngine(throwExceptionAtFirstTime);
    TestSparderPlanExec exec = new TestSparderPlanExec(engine);
    QueryContext.current().setRetrySecondStorage(false);
    Assert.assertNull(exec.executeToIterable(null, null).getRows());
    Assert.assertEquals(2, throwExceptionAtFirstTime.callNumber);
    Assert.assertTrue(QueryContext.current().isForceTableIndex());
    Assert.assertTrue(QueryContext.current().getSecondStorageUsageMap().isEmpty());
    //Now QueryContext.current().isForceTableIndex() == true
    ThrowExceptionAtFirstTime throwExceptionAtFirstTime2 = new ThrowExceptionAtFirstTime(true);
    ThrownExceptionEngine engine2 = new ThrownExceptionEngine(throwExceptionAtFirstTime2);
    exec.updateEngine(engine2);
    try {
        Assert.assertThrows(SparkException.class, () -> exec.executeToIterable(null, null));
    } finally {
        Assert.assertEquals(1, throwExceptionAtFirstTime2.callNumber);
        Assert.assertTrue(QueryContext.current().isForceTableIndex());
        Assert.assertTrue(QueryContext.current().getSecondStorageUsageMap().size() > 0);
    }
}

