void testRowFilter() {
    String sql = "select a, (select count(*) from DB3.aa a1 order by a)\n" + "from ttt join (select a,b from (select * from DB.t t1), (select * from DB.bb)), tt\n" + "where c in (select * from tt) and d > 10 order by abc";
    Map<String, String> whereCond = new TreeMap<>(String.CASE_INSENSITIVE_ORDER);
    whereCond.put("DB.T", "(a > 0 OR b < 0)");
    whereCond.put("DB2.TT", "(aa > 0 OR bb < 0)");
    whereCond.put("DB2.TTT", "(aaa > 0 OR bbb < 0)");
    String expectedSQL = "select a, (select count(*) from DB3.aa a1 order by a)\n" + "from ttt join (select a,b from (select * from DB.t t1 WHERE (T1.a > 0 OR T1.b < 0)), (select * from DB.bb)), tt\n" + "where c in (select * from tt WHERE (TT.aa > 0 OR TT.bb < 0)) and d > 10 AND (TTT.aaa > 0 OR TTT.bbb < 0) AND (TT.aa > 0 OR TT.bb < 0) order by abc";
    Assertions.assertEquals(expectedSQL, RowFilter.rowFilter("DB2", sql, whereCond));
}

