@Test
void testExplicitCcNameToInnerName() {
    // case 1. explicit query name in inner-most sub-query
    String originSql = "select max(CALCS.CC_AUTO_17)\n" + " - min(CALCS.CC_AUTO_17)\n" + "from (select CC_AUTO_17 from tdvt.calcs group by CC_AUTO_17)";
    String ccSql = "select max(CALCS.CC_AUTO_17)\n" + " - min(CALCS.CC_AUTO_17)\n" + "from (select CC_AUTO_17 from tdvt.calcs group by CC_AUTO_17)";
