@Test
public void testBinaryEscapeStringWithRegexWhiteSpace() throws ParseException {
    String sql = "select   ACCOUNT_ID   ,     ACCOUNT_ID     +    1  ,  x'a+ b'  ,X'c *     d', ACCOUNT_ID+2,count(*) from " + "KYLIN_ACCOUNT " + "group   by  ACCOUNT_ID  " + "limit  400   ";
    String sql1 = "select   ACCOUNT_ID   ,  \n   ACCOUNT_ID   \r  +    1  ,  x'a+ b'  ,X'c *     d',\f ACCOUNT_ID+2,count(*) from " + "KYLIN_ACCOUNT " + "group   by  ACCOUNT_ID  " + "limit  400   ";
    String sql2 = "select   ACCOUNT_ID   ,  \n\n   ACCOUNT_ID   \r\r  +    1  ,  x'a+ b'  ,X'c *     d',\f ACCOUNT_ID+2,count(*) from " + "KYLIN_ACCOUNT " + "group   by  ACCOUNT_ID  " + "limit  400   ";
    String sql3 = "select \n  ACCOUNT_ID   ,  \n\n\r\t   ACCOUNT_ID   \r\r  +    1  ,  x'a+ b'  ,X'c *     d',\f ACCOUNT_ID+2,count(*) from " + "KYLIN_ACCOUNT " + "group   by  ACCOUNT_ID  " + "limit  400   ";
    testBinary(sql);
    testBinary(sql1);
    testBinary(sql2);
    testBinary(sql3);
}

@Test
public void testExtractEpoch() throws ParseException {
    String sql = "SELECT ((EXTRACT(EPOCH FROM (DATE '2050-01-01')) / ( 60 * 60 * 24)) + (365 * 70 + 17)) AS \"TEMP(Test)(3947742720)(0)\" FROM \"TDVT\".\"CALCS\" \"CALCS\" HAVING (COUNT(1) > 0)";
    WhiteSpaceParser whiteSpaceParser = new WhiteSpaceParser(dialect, sql.trim());
    String parsed = whiteSpaceParser.parse();
    String real = "SELECT (({fn EPOCH((DATE '2050-01-01' ))} /  (60 *  60 *  24 ) ) +  (365 *  70 +  17 ) ) AS \"TEMP(Test)(3947742720)(0)\" FROM \"TDVT\" . \"CALCS\" \"CALCS\" HAVING (COUNT (1 ) > 0 ) ";
    Assert.assertEquals(real, parsed);
}

@Test
public void testEnableReplaceDynamicParams() {
    NProjectManager projectManager = NProjectManager.getInstance(KylinConfig.getInstanceFromEnv());
    projectManager.updateProject(project_0, copyForWrite -> {
        copyForWrite.getOverrideKylinProps().put("kylin.query.replace-dynamic-params-enabled", "true");
    });
    WithToSubQueryTransformer withToSubQueryTransformer = new WithToSubQueryTransformer();
    String originSql = "with t1 as (select * from KYLIN_SALES WHERE SELLER_ID=10000458)\n" + "select * from t1\n" + "union select * from KYLIN_SALES WHERE SELLER_ID=10000896\n" + "LIMIT 500";
    {
        String expectedSql = "SELECT *\n" + "FROM (SELECT *\n" + "FROM KYLIN_SALES\n" + "WHERE SELLER_ID = 10000458) AS T1\n" + "UNION\n" + "SELECT *\n" + "FROM KYLIN_SALES\n" + "WHERE SELLER_ID = 10000896\n" + "FETCH NEXT 500 ROWS ONLY";
        String transformedSql = withToSubQueryTransformer.transform(originSql, project_0, null);
        Assert.assertEquals(expectedSql, transformedSql);
    }
    {
        String transformedSql = withToSubQueryTransformer.transform(originSql, project_1, null);
        Assert.assertEquals(originSql, transformedSql);
    }
    projectManager.updateProject(project_0, copyForWrite -> {
        copyForWrite.getOverrideKylinProps().remove("kylin.query.replace-dynamic-params-enabled");
    });
}

