@Test
public void testCreateTraces() {
    getTestConfig().setProperty("kylin.query.spark-job-trace-enabled", "false");
    final QueryContext queryContext = QueryContext.current();
    queryContext.getQueryTrace().startSpan(QueryTrace.SQL_TRANSFORMATION);
    queryContext.getQueryTrace().startSpan(QueryTrace.SQL_PARSE_AND_OPTIMIZE);
    queryContext.getQueryTrace().startSpan(QueryTrace.PREPARE_AND_SUBMIT_JOB);
    queryContext.getQueryTrace().endLastSpan();
    val list = QueryMetricsContext.createTraces(queryContext);
    Assert.assertEquals(1, list.stream().filter(span -> span.getName().equals(QueryTrace.SPARK_JOB_EXECUTION)).count());
    Assert.assertEquals(0, list.stream().filter(span -> span.getName().equals(QueryTrace.PREPARE_AND_SUBMIT_JOB)).count());
    final String sql = "select * from test_with_otherError";
    QueryMetricsContext.start(queryContext.getQueryId(), "localhost:7070");
    queryContext.setProject("default");
    queryContext.setAclInfo(new QueryContext.AclInfo("ADMIN", Sets.newHashSet("g1"), true));
    queryContext.getQueryTagInfo().setHitExceptionCache(true);
    queryContext.getMetrics().setServer("localhost:7070");
    queryContext.setPushdownEngine("HIVE");
    queryContext.setUserSQL(sql);
    queryContext.getMetrics().setCorrectedSql(massageSql(queryContext));
    final QueryMetricsContext metricsContext = QueryMetricsContext.collect(queryContext);
    List<QueryHistoryInfo.QueryTraceSpan> traces = metricsContext.getQueryHistoryInfo().getTraces();
    Assert.assertEquals(0, traces.stream().filter(span -> span.getName().equals(QueryTrace.PREPARE_AND_SUBMIT_JOB)).count());
    Assert.assertEquals(1, traces.stream().filter(span -> span.getName().equals(QueryTrace.SPARK_JOB_EXECUTION)).count());
    getTestConfig().setProperty("kylin.query.spark-job-trace-enabled", "true");
    List<QueryHistoryInfo.QueryTraceSpan> list1 = QueryMetricsContext.createTraces(queryContext);
    Assert.assertEquals(1, list1.stream().filter(span -> span.getName().equals(QueryTrace.PREPARE_AND_SUBMIT_JOB)).count());
    Assert.assertEquals(0, list1.stream().filter(span -> span.getName().equals(QueryTrace.SPARK_JOB_EXECUTION)).count());
}

@Test
public void testSparkKilled() {
    // first check should be good
    Assert.assertTrue(SparderEnv.isSparkAvailable());
    // stop spark and check again, the spark context should auto-restart
    SparderEnv.getSparkSession().stop();
    Assert.assertFalse(SparderEnv.isSparkAvailable());
    SparkContextCanary.getInstance().monitor();
    Assert.assertTrue(SparderEnv.isSparkAvailable());
    SparkContextCanary.getInstance().monitor();
    Assert.assertEquals(0, SparkContextCanary.getInstance().getErrorAccumulated());
}

@Test
public void testSparkTimeout() {
    // first check should be GOOD
    Assert.assertTrue(SparderEnv.isSparkAvailable());
    // set kylin.canary.sqlcontext-error-response-ms to 1
    // And SparkContextCanary numberCount will timeout
    Assert.assertEquals(0, SparkContextCanary.getInstance().getErrorAccumulated());
    overwriteSystemProp("kylin.canary.sqlcontext-error-response-ms", "1");
    SparkContextCanary.getInstance().monitor();
    // errorAccumulated increase
    Assert.assertEquals(1, SparkContextCanary.getInstance().getErrorAccumulated());
    // reach threshold to restart spark. Reset errorAccumulated.
    SparkContextCanary.getInstance().monitor();
    Assert.assertEquals(2, SparkContextCanary.getInstance().getErrorAccumulated());
    SparkContextCanary.getInstance().monitor();
    Assert.assertEquals(3, SparkContextCanary.getInstance().getErrorAccumulated());
    Assert.assertTrue(SparderEnv.isSparkAvailable());
    SparderEnv.getSparkSession().stop();
}

