@Test
public void testPrepareSQL() {
    verifyPrepareResult("select a from b where c = ? and d = ?", new String[] { "123", "d'2019-01-01'" }, "select a from b where c = '123' and d = 'd'2019-01-01''");
    verifyPrepareResult("select \"a\" from \"b\" where \"c\" = ? and \"e\" = 'abc' and d = ?;", new String[] { "123", "d'2019-01-01'" }, "select \"a\" from \"b\" where \"c\" = '123' and \"e\" = 'abc' and d = 'd'2019-01-01'';");
    verifyPrepareResult("select * from (select \"a\", '?' as q from \"b\" where \"c\" = ? and \"e\" = 'abc' and d = ?) join (select \"b\" from z where x = ?)", new String[] { "123", "d'2019-01-01'", "abcdef" }, "select * from (select \"a\", '?' as q from \"b\" where \"c\" = '123' and \"e\" = 'abc' and d = 'd'2019-01-01'') join (select \"b\" from z where x = 'abcdef')");
    verifyPrepareResult("select a from b where c = ? and d = ? and e = ? and f = ? and g = ? and h = ? and i = ? and j = ? and k = ?", new PrepareSqlStateParam[] { new PrepareSqlStateParam(Integer.class.getCanonicalName(), "123"), new PrepareSqlStateParam(Double.class.getCanonicalName(), "123.0"), new PrepareSqlStateParam(String.class.getCanonicalName(), "a string"), new PrepareSqlStateParam(Date.class.getCanonicalName(), "2019-01-01"), new PrepareSqlStateParam(Timestamp.class.getCanonicalName(), "2019-01-01 00:12:34.123"), new PrepareSqlStateParam(Short.class.getCanonicalName(), "-128"), new PrepareSqlStateParam(Long.class.getCanonicalName(), "-2147483648"), new PrepareSqlStateParam(Boolean.class.getCanonicalName(), "true"), new PrepareSqlStateParam(BigDecimal.class.getCanonicalName(), "-9223372036854775") }, "select a from b where c = 123 and d = 123.0 and e = 'a string' and f = date'2019-01-01' and g = timestamp'2019-01-01 00:12:34.123' " + "and h = -128 and i = -2147483648 and j = true and k = -9223372036854775");
}

