@Test
public void testValidateModel() {
    prepareManger();
    PowerMockito.stub(PowerMockito.method(ExecutableManager.class, "getInstance", KylinConfig.class, String.class)).toReturn(executableManager);
    List<String> jobs = Collections.singletonList("job1");
    AbstractExecutable job1 = PowerMockito.mock(AbstractExecutable.class);
    PowerMockito.when(job1.getStatus()).thenReturn(ExecutableState.READY, ExecutableState.PENDING, ExecutableState.RUNNING, ExecutableState.PAUSED, ExecutableState.SUCCEED);
    PowerMockito.when(job1.getJobType()).thenReturn(JobTypeEnum.EXPORT_TO_SECOND_STORAGE);
    Mockito.when(job1.getProject()).thenReturn("project");
    Mockito.when(job1.getTargetModelId()).thenReturn("modelId");
    Mockito.when(executableManager.getJobs()).thenReturn(jobs);
    Mockito.when(executableManager.getJob("job1")).thenReturn(job1);
    //job status: Ready
    assertThrows(MsgPicker.getMsg().getSecondStorageConcurrentOperate(), KylinException.class, () -> SecondStorageJobUtil.validateModel("project", "modelId"));
    //job status: Pending
    assertThrows(MsgPicker.getMsg().getSecondStorageConcurrentOperate(), KylinException.class, () -> SecondStorageJobUtil.validateModel("project", "modelId"));
    //job status: Running
    assertThrows(MsgPicker.getMsg().getSecondStorageConcurrentOperate(), KylinException.class, () -> SecondStorageJobUtil.validateModel("project", "modelId"));
    //job status: Paused
    assertThrows(MsgPicker.getMsg().getSecondStorageConcurrentOperate(), KylinException.class, () -> SecondStorageJobUtil.validateModel("project", "modelId"));
    //job status: Succeed
    SecondStorageJobUtil.validateModel("project", "modelId");
}

