@Test
public void testAddStepInMerging() {
    NDataflowManager dsMgr = NDataflowManager.getInstance(config, getProject());
    NDataflow df = dsMgr.getDataflow("89af4ee2-2cdb-4b07-b39e-4c29856309aa");
    NDataflow flowCopy = dsMgr.getDataflow(df.getUuid()).copy();
    NDataflowUpdate update = new NDataflowUpdate(df.getUuid());
    NDataSegment firstSeg = NDataSegment.empty();
    firstSeg.setSegmentRange(new SegmentRange.TimePartitionedSegmentRange(SegmentRange.dateToLong("2010-01-02"), SegmentRange.dateToLong("2011-01-01")));
    firstSeg.setStatus(SegmentStatusEnum.READY);
    firstSeg.setId(RandomUtil.randomUUIDStr());
    NDataSegment secondSeg = NDataSegment.empty();
    secondSeg.setSegmentRange(new SegmentRange.TimePartitionedSegmentRange(SegmentRange.dateToLong("2011-01-01"), SegmentRange.dateToLong("2013-01-01")));
    secondSeg.setStatus(SegmentStatusEnum.READY);
    secondSeg.setId(RandomUtil.randomUUIDStr());
    Segments<NDataSegment> mergingSegments = new Segments<>();
    mergingSegments.add(firstSeg);
    mergingSegments.add(secondSeg);
    flowCopy.setSegments(mergingSegments);
    update.setToRemoveSegs(df.getSegments().toArray(new NDataSegment[0]));
    dsMgr.updateDataflow(update);
    NDataSegment mergedSegment = dsMgr.mergeSegments(flowCopy, new SegmentRange.TimePartitionedSegmentRange(SegmentRange.dateToLong("2010-01-02"), SegmentRange.dateToLong("2013-01-01")), true);
    Set<LayoutEntity> layouts = Sets.newHashSet(flowCopy.getIndexPlan().getAllLayouts());
    NSparkMergingJob job = NSparkMergingJob.merge(mergedSegment, Sets.newLinkedHashSet(layouts), "ADMIN", RandomUtil.randomUUIDStr());
    Assert.assertEquals("89af4ee2-2cdb-4b07-b39e-4c29856309aa", job.getTargetSubject());
    NSparkExecutable resourceDetectStep = job.getResourceDetectStep();
    Assert.assertEquals(ResourceDetectBeforeMergingJob.class.getName(), resourceDetectStep.getSparkSubmitClassName());
    Assert.assertEquals(ExecutableConstants.STEP_NAME_DETECT_RESOURCE, resourceDetectStep.getName());
    job.getParams().forEach((key, value) -> Assert.assertEquals(value, resourceDetectStep.getParam(key)));
    Assert.assertEquals(config.getJobTmpMetaStoreUrl(getProject(), resourceDetectStep.getId()).toString(), resourceDetectStep.getDistMetaUrl());
    NSparkExecutable mergeStep = job.getSparkMergingStep();
    Assert.assertEquals(config.getSparkMergeClassName(), mergeStep.getSparkSubmitClassName());
    Assert.assertEquals(ExecutableConstants.STEP_NAME_MERGER_SPARK_SEGMENT, mergeStep.getName());
    job.getParams().forEach((key, value) -> Assert.assertEquals(value, mergeStep.getParam(key)));
    Assert.assertEquals(config.getJobTmpMetaStoreUrl(getProject(), mergeStep.getId()).toString(), mergeStep.getDistMetaUrl());
    NSparkCleanupAfterMergeStep cleanStep = job.getCleanUpAfterMergeStep();
    job.getParams().forEach((key, value) -> {
        if (key.equalsIgnoreCase(NBatchConstants.P_SEGMENT_IDS)) {
            final Set<String> needDeleteSegmentIds = df.getMergingSegments(mergedSegment).stream().map(NDataSegment::getId).collect(Collectors.toSet());
            Assert.assertEquals(needDeleteSegmentIds, cleanStep.getSegmentIds());
        } else {
            Assert.assertEquals(value, mergeStep.getParam(key));
        }
    });
    Assert.assertEquals(config.getJobTmpMetaStoreUrl(getProject(), cleanStep.getId()).toString(), cleanStep.getDistMetaUrl());
}

@Test
public void testSparkJobOnYarn() throws IOException, InterruptedException {
    KylinConfig config = KylinConfig.getInstanceFromEnv();
    config.setProperty("kylin.env.hdfs-working-dir", "hdfs://sandbox/kylin");
    config.setProperty("kylin.env", "DEV");
    config.setProperty("kylin.engine.spark.job-jar", "../assembly/target/ke-assembly-4.0.0-SNAPSHOT-job.jar");
    NDataflowManager dsMgr = NDataflowManager.getInstance(config, "default");
    ExecutableManager execMgr = ExecutableManager.getInstance(config, "default");
    NDataflow df = dsMgr.getDataflow("89af4ee2-2cdb-4b07-b39e-4c29856309aa");
    NDataflowUpdate update = new NDataflowUpdate(df.getUuid());
    update.setToRemoveSegs(df.getSegments().toArray(new NDataSegment[0]));
    dsMgr.updateDataflow(update);
    NDataSegment oneSeg = dsMgr.appendSegment(df, new SegmentRange.TimePartitionedSegmentRange(0L, SegmentRange.dateToLong("2012-06-01")));
    List<LayoutEntity> layouts = df.getIndexPlan().getAllLayouts();
    NSparkCubingJob job = NSparkCubingJob.create(Sets.newHashSet(oneSeg), Sets.newLinkedHashSet(layouts), "ADMIN", null);
    // launch the job
    execMgr.addJob(job);
    ExecutableState status = wait(job);
    Assert.assertEquals(ExecutableState.SUCCEED, status);
    df = dsMgr.getDataflow("89af4ee2-2cdb-4b07-b39e-4c29856309aa");
    oneSeg = dsMgr.appendSegment(df, new SegmentRange.TimePartitionedSegmentRange(SegmentRange.dateToLong("2012-06-01"), SegmentRange.dateToLong("2013-06-01")));
    job = NSparkCubingJob.create(Sets.newHashSet(oneSeg), Sets.newLinkedHashSet(layouts), "ADMIN", null);
    // launch the job
    execMgr.addJob(job);
    // wait job done
    status = wait(job);
    Assert.assertEquals(ExecutableState.SUCCEED, status);
    df = dsMgr.getDataflow("89af4ee2-2cdb-4b07-b39e-4c29856309aa");
    oneSeg = dsMgr.mergeSegments(df, new SegmentRange.TimePartitionedSegmentRange(0L, SegmentRange.dateToLong("2013-06-01")), false);
    NSparkMergingJob mergeJob = NSparkMergingJob.merge(oneSeg, Sets.newLinkedHashSet(layouts), "ADMIN", RandomUtil.randomUUIDStr());
    // launch the job
    execMgr.addJob(mergeJob);
    // wait job done
    status = wait(mergeJob);
    Assert.assertEquals(ExecutableState.SUCCEED, status);
}

