@SuppressWarnings("unchecked")
public void testMarkFilePageRemoved() {
    // Add some dummy data to the cacheManager before testing
    PageId pageId1 = new PageId("fileId1", 0);
    PageId pageId2 = new PageId("fileId1", 1);
    PageId pageId3 = new PageId("fileId2", 0);
    PageId pageId4 = new PageId("fileId3", 0);
    cacheManager.markFilePageCached(pageId1);
    cacheManager.markFilePageCached(pageId2);
    cacheManager.markFilePageCached(pageId3);
    //
    ConcurrentHashMap<String, ManagerOfCacheFileContent.FileMeta> //
    fileMetas = (ConcurrentHashMap<String, ManagerOfCacheFileContent.FileMeta>) ReflectionTestUtils.getField(cacheManager, "fileMetas");
    ManagerOfCacheFileContent.FileMeta fileMeta1 = fileMetas.get("fileId1");
    ManagerOfCacheFileContent.FileMeta fileMeta2 = fileMetas.get("fileId2");
    assertNotNull(fileMeta1);
    assertNotNull(fileMeta2);
    cacheManager.markFilePageRemoved(pageId1);
    cacheManager.markFilePageRemoved(pageId2);
    cacheManager.markFilePageRemoved(pageId4);
    ManagerOfCacheFileContent.FileMeta fileMeta3 = fileMetas.get("fileId3");
    assertNotNull(fileMeta3);
    assertTrue(fileMeta1.cachedPageIndex.isEmpty());
    assertFalse(fileMeta2.cachedPageIndex.isEmpty());
    assertTrue(fileMeta3.cachedPageIndex.isEmpty());
}

@Test
public void makeIOException() {
    {
        IOException ioException = new IOException("Test IOException");
        IOException result = ManagerOfCacheFileStatus.makeIOException(ioException);
        assertSame(ioException, result);
    }
    {
        IOException ioException = new IOException("Test IOException");
        ExecutionException executionException = new ExecutionException(ioException);
        IOException result = ManagerOfCacheFileStatus.makeIOException(executionException);
        assertSame(ioException, result);
    }
    {
        IOException ioException = new IOException("Test IOException");
        UncheckedExecutionException uncheckedExecutionException = new UncheckedExecutionException(ioException);
        IOException result = ManagerOfCacheFileStatus.makeIOException(uncheckedExecutionException);
        assertSame(ioException, result);
    }
    {
        IOException ioException = new IOException("Test IOException");
        Throwable wrappedException = new RuntimeException(ioException);
        IOException result = ManagerOfCacheFileStatus.makeIOException(wrappedException);
        assertSame(ioException, result);
    }
    {
        Throwable otherException = new RuntimeException("Test RuntimeException");
        IOException result = ManagerOfCacheFileStatus.makeIOException(otherException);
        assertEquals(IOException.class, result.getClass());
        assertEquals(otherException, result.getCause());
    }
}

@Test
public void testExtractAcceptCacheTimeFromSql() {
    {
        String[] pair = extractAcceptCacheTime("");
        Assert.assertArrayEquals(new String[] { "", null }, pair);
    }
    {
        String[] pair = extractAcceptCacheTime("ACCEPT_CACHE_TIME");
        Assert.assertArrayEquals(new String[] { "ACCEPT_CACHE_TIME", null }, pair);
    }
    {
        String[] pair = extractAcceptCacheTime("select * from xxx /*+ ACCEPT_CACHE_TIME(158176387682000) */");
        Assert.assertArrayEquals(new String[] { "select * from xxx ", "158176387682000" }, pair);
    }
    {
        String[] pair = extractAcceptCacheTime("/*+ ACCEPT_CACHE_TIME(158176387682000) */\nselect * from xxx");
        Assert.assertArrayEquals(new String[] { "\nselect * from xxx", "158176387682000" }, pair);
    }
    {
        String[] pair = extractAcceptCacheTime("/*+ ACCEPT_CACHE_TIME(158176387682000, 2021-03-28T12:33:54) */\nselect * from xxx");
        Assert.assertArrayEquals(new String[] { "\nselect * from xxx", "158176387682000" }, pair);
    }
    // now 2023/2/27:  1677466066216
    // big enough:   158176387682000
    System.out.println("System.currentTimeMillis() -- " + System.currentTimeMillis());
}

