    KylinConfig kylinConfig = getTestConfig();
    kylinConfig.setProperty("kylin.kafka-jaas.enabled", "true");
    File testKeyTab = new File(KylinConfig.getKylinConfDir() + File.separator + "test.keytab");
    // jaas not exist
    Assert.assertThrows(READ_KAFKA_JAAS_FILE_ERROR.getMsg(), KylinException.class, () -> StreamingJobUtils.extractKafkaJaasConf(true));
    // jaas keytab key not exist
    FileUtils.write(new File(kapConfig.getKafkaJaasConfPath()), "KafkaClient { " + "com.sun.security.auth.module.Krb5LoginModule required " + "useKeyTab=true " + "storeKey=true " + "principal=\"kylin@DEV.COM\" " + "serviceName=\"kafka\";" + " };", StandardCharsets.UTF_8);
    Assert.assertNull(StreamingJobUtils.getJaasKeyTabAbsPath());
    // jaas exist but keytab not exist
    FileUtils.write(new File(kapConfig.getKafkaJaasConfPath()), "KafkaClient { " + "com.sun.security.auth.module.Krb5LoginModule required " + "useKeyTab=true " + "storeKey=true " + "keyTab=\"" + testKeyTab + "\" " + "principal=\"kylin@DEV.COM\" " + "serviceName=\"kafka\";" + " };", StandardCharsets.UTF_8);
    Assert.assertThrows(KAFKA_JAAS_FILE_KEYTAB_NOT_EXISTS.getMsg(), KylinException.class, () -> StreamingJobUtils.extractKafkaJaasConf(true));
    // all exist
    FileUtils.write(testKeyTab, "test", StandardCharsets.UTF_8);
    val text = StreamingJobUtils.extractKafkaJaasConf(true);
    Assert.assertNotNull(text);
    String keyTabAbsPath = StreamingJobUtils.getJaasKeyTabAbsPath();
