    jobFilter = new StreamingJobFilter("stream_merge", Collections.EMPTY_LIST, Collections.EMPTY_LIST, Collections.EMPTY_LIST, PROJECT, "last_modified", true);
    list = streamingJobService.getStreamingJobList(jobFilter, 0, 20);
