    jobFilter = new StreamingJobFilter("stream_merge2", Collections.EMPTY_LIST, Collections.EMPTY_LIST, Collections.EMPTY_LIST, PROJECT, "last_modified", true);
    list = streamingJobService.getStreamingJobList(jobFilter, 0, 20);
    Assert.assertEquals(0, list.getTotalSize());
    jobFilter = new StreamingJobFilter("", Arrays.asList("stream_merge1"), Collections.EMPTY_LIST, Collections.EMPTY_LIST, PROJECT, "last_modified", true);
    list = streamingJobService.getStreamingJobList(jobFilter, 0, 20);
    Assert.assertEquals(2, list.getTotalSize());
    // job types filter
    jobFilter = new StreamingJobFilter("", Collections.EMPTY_LIST, Arrays.asList("STREAMING_BUILD"), Collections.EMPTY_LIST, PROJECT, "last_modified", true);
    list = streamingJobService.getStreamingJobList(jobFilter, 0, 20);
    Assert.assertEquals(6, list.getValue().size());
    // status filter
    val config = getTestConfig();
    val jobMgr = StreamingJobManager.getInstance(config, PROJECT);
    jobMgr.updateStreamingJob(MODEL_ID + "_build", copyForWrite -> {
        copyForWrite.setCurrentStatus(JobStatusEnum.RUNNING);
    });
    jobFilter = new StreamingJobFilter("", Collections.EMPTY_LIST, Collections.EMPTY_LIST, Arrays.asList("RUNNING"), PROJECT, "last_modified", true);
    list = streamingJobService.getStreamingJobList(jobFilter, 0, 20);
    Assert.assertEquals(3, list.getTotalSize());
    // project filter
    jobFilter = new StreamingJobFilter("", Collections.EMPTY_LIST, Collections.EMPTY_LIST, Collections.EMPTY_LIST, PROJECT, "last_modified", true);
    list = streamingJobService.getStreamingJobList(jobFilter, 0, 4);
    Assert.assertEquals(4, list.getValue().size());
    // sort & reverse
    Assert.assertTrue(list.getValue().get(0).getLastModified() >= list.getValue().get(1).getLastModified());
    Assert.assertTrue(list.getValue().get(1).getLastModified() >= list.getValue().get(2).getLastModified());
    Assert.assertTrue(list.getValue().get(2).getLastModified() >= list.getValue().get(3).getLastModified());
    jobFilter = new StreamingJobFilter("", Collections.EMPTY_LIST, Collections.EMPTY_LIST, Collections.EMPTY_LIST, "", "last_modified", false);
    list = streamingJobService.getStreamingJobList(jobFilter, 0, 20);
    Assert.assertTrue(list.getValue().get(0).getLastModified() <= list.getValue().get(1).getLastModified());
    Assert.assertTrue(list.getValue().get(1).getLastModified() <= list.getValue().get(2).getLastModified());
    Assert.assertTrue(list.getValue().get(2).getLastModified() <= list.getValue().get(3).getLastModified());
    // project & page_size filter
    jobFilter = new StreamingJobFilter("", Collections.EMPTY_LIST, Collections.EMPTY_LIST, Collections.EMPTY_LIST, "", "last_modified", true);
    list = streamingJobService.getStreamingJobList(jobFilter, 0, 4);
    Assert.assertEquals(11, list.getTotalSize());
    Assert.assertEquals(4, list.getValue().size());
    // offset filter
    list = streamingJobService.getStreamingJobList(jobFilter, 0, 2);
    Assert.assertEquals(2, list.getValue().size());
    streamingJobsStatsManager.deleteAllStreamingJobStats();
    jobMgr.updateStreamingJob(MODEL_ID + "_build", copyForWrite -> {
        copyForWrite.setCurrentStatus(JobStatusEnum.LAUNCHING_ERROR);
    });
    jobFilter = new StreamingJobFilter("", Collections.EMPTY_LIST, Collections.EMPTY_LIST, Arrays.asList("ERROR"), PROJECT, "last_modified", true);
    list = streamingJobService.getStreamingJobList(jobFilter, 0, 20);
