    Assert.assertEquals("/just/a/path/", simpleMetadataUrl);
    simpleMetadataUrl = metadataToolHelper.getMetadataUrl(simplePath, false, kylinConfig);
    Assert.assertEquals("/just/a/path/", simpleMetadataUrl);
}

